package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.jsoup.nodes.Node#siblingIndex()
 */
public class Node_siblingIndex_TriageGen0Test {









    @Test
    public void testSiblingIndex_AfterRemoval() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling2 = parent.appendElement("span");
        Element sibling3 = parent.appendElement("p");

        // Remove the first sibling
        sibling1.remove();

        // sibling2 was index 1, but after removal, it becomes the first sibling (index 0)
        Assert.assertEquals(0, sibling2.siblingIndex());
        Assert.assertEquals(1, sibling3.siblingIndex());
    }




}
